<?php
require 'config.php'; wajib_login(); if(!role('pengepul')){header('Location: dashboard.php');exit;} $uid=(int)$_SESSION['user']['id_user'];$msg=''; if(isset($_GET['aksi'],$_GET['id'])){$id=(int)$_GET['id'];$aksi=$_GET['aksi'];$q=$conn->prepare('SELECT p.*,s.stok_kg FROM penjualan_pengepul p JOIN sampah s ON s.id_sampah=p.id_sampah WHERE p.id_penjualan=? AND p.id_pengepul=?');$q->bind_param('ii',$id,$uid);$q->execute();$p=$q->get_result()->fetch_assoc();if($p&&$p['status']==='pending'){if($aksi==='setujui'){if($p['berat_kg']>$p['stok_kg']){$msg='Stok admin tidak mencukupi.';}else{$conn->begin_transaction();$q=$conn->prepare("UPDATE penjualan_pengepul SET status='selesai' WHERE id_penjualan=?");$q->bind_param('i',$id);$q->execute();$q=$conn->prepare('UPDATE sampah SET stok_kg=stok_kg-? WHERE id_sampah=?');$q->bind_param('di',$p['berat_kg'],$p['id_sampah']);$q->execute();$conn->commit();$msg='Pembelian disetujui dan stok admin berkurang.';}}elseif($aksi==='tolak'){$q=$conn->prepare("UPDATE penjualan_pengepul SET status='ditolak' WHERE id_penjualan=?");$q->bind_param('i',$id);$q->execute();$msg='Pembelian ditolak.';}}} $q=$conn->prepare('SELECT p.*,s.jenis_sampah,u.nama admin_nama FROM penjualan_pengepul p JOIN sampah s ON s.id_sampah=p.id_sampah JOIN user u ON u.id_user=p.id_admin WHERE p.id_pengepul=? ORDER BY p.tanggal DESC');$q->bind_param('i',$uid);$q->execute();$rows=$q->get_result();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beli Sampah</title><link rel="stylesheet" href="style.css?v=3"></head><body><?php include 'nav.php'; ?><main class="container"><h1>Penawaran Sampah dari Admin</h1><?php if($msg): ?><div class="alert"><?=e($msg)?></div><?php endif; ?><div class="panel table-wrap"><table><tr><th>Tanggal</th><th>Admin</th><th>Sampah</th><th>Berat</th><th>Harga/kg</th><th>Total</th><th>Status</th><th>Aksi</th></tr><?php while($r=$rows->fetch_assoc()): ?><tr><td><?=e($r['tanggal'])?></td><td><?=e($r['admin_nama'])?></td><td><?=e($r['jenis_sampah'])?></td><td><?=number_format($r['berat_kg'],2,',','.')?> kg</td><td>Rp <?=number_format($r['harga_per_kg'],0,',','.')?></td><td>Rp <?=number_format($r['total_rp'],0,',','.')?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'): ?><a class="btn small success" href="?aksi=setujui&id=<?=$r['id_penjualan']?>">Beli</a><a class="btn small danger" href="?aksi=tolak&id=<?=$r['id_penjualan']?>">Tolak</a><?php else: ?>-<?php endif; ?></td></tr><?php endwhile; ?></table></div></main></body></html>